function [power_signals, voltage_signals, current_signals, angle_signals] = mfun_gfm_monitored_signals(fbk_in, ref_in, p)
%MFUN_GFM_MONITORED_SIGNALS Block Monitored signals of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the Simulink model, which adds its folder to the MATLAB
%   path. The parameters are the fields of the struct p (from the mask, [] as NaN).
fbk = gfm_feedbacks_unpack(fbk_in);
ref = gfm_references_unpack(ref_in);
% Monitored signals
% The currents and the angle in the coordinates of v_c
rot = exp(-1i*angle(fbk.v_c));
power_signals = [ref.p_g; fbk.p_g; fbk.q_g];
voltage_signals = [ref.v_c; abs(fbk.v_c)];
current_signals = [ ...
    real(rot * ref.i_c);
    real(rot * fbk.i_c);
    imag(rot * ref.i_c);
    imag(rot * fbk.i_c)];
angle_signals = [wrap(fbk.theta_c + angle(fbk.v_c))];
end

function s = gfm_feedbacks_unpack(u)
%GFM_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_c_zoh', complex(u(5), u(6)), ...
    'v_c', complex(u(7), u(8)), ...
    'u_g', complex(u(9), u(10)), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'theta_c', u(13), ...
    'w_c', u(14));
end

function s = gfm_references_unpack(u)
%GFM_REFERENCES_UNPACK Struct of the signal vector u.
s = struct( ...
    'p_g', u(1), ...
    'v_c', u(2), ...
    'i_c', complex(u(3), u(4)), ...
    'u_c', complex(u(5), u(6)));
end

function theta = wrap(theta)
%WRAP Limit the angle into the range [-pi, pi), as numpy.mod does.
x = rem(theta + pi, 2*pi);
if x < 0
    x = x + 2*pi;
end
theta = x - pi;
end
